  <script>
    function toggleMenu() {
      const nav = document.getElementById("navMenu");
      nav.classList.toggle("hidden");
      nav.classList.toggle("flex");
    }

    document.getElementById("tiketInput").addEventListener("keypress", function (event) {
      if (event.key === "Enter") {
        cekResi();
      }
    });

    function cekResi() {
      const input = document.getElementById("tiketInput");
      const hasil = document.getElementById("hasilTiket");
      const tiket = input.value.trim();

      if (!tiket) {
        hasil.className = "mx-auto mt-4 max-w-[500px] text-center text-sm text-red-600 font-medium";
        hasil.textContent = "Silakan masukkan nomor tiket terlebih dahulu.";
        return;
      }

      hasil.className = "mx-auto mt-4 max-w-[500px] text-center text-sm text-emerald-600 font-medium";
      hasil.innerHTML =
        "Nomor tiket <strong>" + tiket +
        "</strong> diterima. Sistem tiket dapat dihubungkan ke database/backend TeFA.";
    }

    document.querySelectorAll("#navMenu a").forEach(link => {
      link.addEventListener("click", () => {
        const nav = document.getElementById("navMenu");
        if (window.innerWidth < 768) {
          nav.classList.add("hidden");
          nav.classList.remove("flex");
        }
      });
    });
  </script>


